// Verus program: rotate a vector of integers left by `offset`.
// For each i in [0, n), b[i] == a[(i + offset) % n] where n = a.len().
// Handles n == 0 by returning an empty vector.

use vstd::prelude::*;

verus! {

fn rotate(a: Vec<int>, offset: usize) -> (b: Vec<int>)
    requires
        a.len() < 1_000_000,
        offset < 1_000_000,
        // Per problem statement: both are strictly less than half of usize::MAX.
        // This ensures (i + offset) doesn't overflow for any i < a.len().
        a.len() < (usize::MAX / 2),
        offset < (usize::MAX / 2),
    ensures
        b.len() == a.len(),
        // Empty in, empty out.
        a.len() == 0 ==> b.len() == 0,
        // Rotation property for non-empty arrays.
        a.len() > 0 ==>
            forall|i: int|
                0 <= i && i < b.len() as int ==>
                    b[i] == a[((i as usize + offset) % a.len()) as int],
{
    let n = a.len();

    if n == 0 {
        // For empty input, just return empty output.
        return Vec::<int>::new();
    }

    // Reduce offset modulo n to avoid repeated large offsets.
    let k = offset % n;

    let mut b: Vec<int> = Vec::with_capacity(n);
    let mut i: usize = 0;

    while i < n
        invariant
            n == a.len(),
            n > 0,
            k < n,
            b.len() == i,
            i <= n,
            // Established rotation property for elements already pushed.
            forall|j: int|
                0 <= j && j < i as int ==>
                    b[j] == a[((j as usize + k) % n) as int],
    {
        // Since n < usize::MAX/2 and k < n, (i + k) cannot overflow.
        let src = (i + k) % n;
        b.push(a[src as int]);
        i += 1;
    }

    b
}

} // verus!